'use strict';
const IG='https://www.instagram.com/vamknam.by/';
const PHONE='+375 44 753-53-10';
const TG='tg://resolve?phone=375447535310';
const A='assets/reference/';
const params=new URLSearchParams(location.search);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<img class="icon ${cls}" src="${A+name}.svg" alt="" width="24" height="24">`;
const photo=(name,alt,cls='',eager=false)=>`<img class="${cls}" src="${A+name}.jpg" alt="${esc(alt)}" ${eager?'fetchpriority="high"':'loading="lazy"'} width="900" height="600">`;
const products=[
 {id:'leaves',name:'Ключница «Листья»',price:45,category:'Ключницы',image:'key-product',homeImage:'leaves',size:'Примерно 30×12 см',description:'Изготовлена из качественной фанеры. Резьба выполнена лазером. Можно добавить имя или надпись. Размер примерно 30×12 см. Каждое изделие делается индивидуально.'},
 {id:'house',name:'Копилка «Домик»',price:38,category:'Копилки',image:'house-bank',description:'Деревянная копилка в форме уютного домика. Аккуратная лазерная резка и натуральная фактура дерева. Можно добавить имя или памятную надпись.'},
 {id:'tree',name:'Панель «Дерево жизни»',price:55,category:'Декор',image:'life-panel',description:'Ажурная деревянная панель «Дерево жизни» для вашего дома. Детальный узор выполнен лазерной резкой. Размер и оформление согласовываются при заказе.'},
 {id:'custom',name:'Идея на заказ',price:40,from:true,category:'На заказ',image:'custom',description:'Ваш дизайн или идея. Расскажите, что хочется создать: подберём форму, размер и персональную надпись, согласуем макет и стоимость.'},
 ...[['leaves','Листья',25],['house','Домик',27],['mountains','Горы',28],['diamond','Орнамент',24],['life','Дерево жизни',29],['owl','Сова',26],['deer','Олень',27],['minimal','Минимализм',23],['heart','Сердце',24],['city','Город',28]].map(([id,name,price])=>({id:'key-'+id,name:'Ключница '+name,price,from:true,category:'Ключницы',image:id==='leaves'?'leaves':'key-'+id,catalog:true,description:'Деревянная ключница с аккуратной лазерной резкой и металлическими крючками. Дизайн, размер и возможность добавить имя или надпись обсудим перед изготовлением.'})),
 {id:'notebook',name:'Деревянный блокнот',category:'Блокноты',image:'notebook',price:null,description:'Блокнот с деревянной обложкой и гравировкой. Рисунок, надпись и стоимость согласовываются индивидуально.'},
 {id:'pig',name:'Копилка «Свинка»',category:'Копилки',image:'pig-bank',price:null,description:'Деревянная копилка с гравировкой. Можно согласовать персональное оформление. Стоимость уточняется при заказе.'},
 {id:'mini-bar',name:'Деревянный мини-бар',category:'Мини-бары',image:'mini-bar',price:null,description:'Компактный деревянный шкафчик для подарка. Размер, наполнение, оформление и цена согласовываются индивидуально. Напитки на изображении показаны для примера.'}
];
const getProduct=id=>products.find(p=>p.id===id);
const productURL=p=>p.id==='leaves'?'product/klyuchnitsa-listya/':`product/?id=${encodeURIComponent(p.id)}`;
const priceHTML=p=>p.price===null?'По запросу':`${p.from?'от ':''}${p.price} ${p.catalog?'руб.':'BYN'}`;
const app=document.querySelector('#app');
const basePath=new URL(document.baseURI).pathname;
const path=('/'+location.pathname.slice(basePath.length)).replace(/\/+$/,'')||'/';
let cart=[];
try {cart=JSON.parse(localStorage.getItem('vamknam-reference-cart-v1')||'[]').filter(x=>getProduct(x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99).map(x=>({...x,text:String(x.text||'').slice(0,140)}));}catch{}
function saveCart(){try{localStorage.setItem('vamknam-reference-cart-v1',JSON.stringify(cart));}catch{}document.querySelectorAll('[data-cart-count]').forEach(el=>el.textContent=cart.reduce((n,x)=>n+x.qty,0));}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500);}
function header(){const order=path==='/how-to-order';const detail=path.startsWith('/product');document.body.className=order?'order-page':detail?'detail-page':path==='/catalog'?'catalog-page':path==='/'?'home-page':'inner-page';(document.querySelector('#header')||document.querySelector('.header')).innerHTML=`<div class="header-inner"><a class="brand" href="./" aria-label="vamknam.by — главная"><img src="assets/logo.jpg" width="62" height="62" alt="Цветочный орнамент мастерской"><span>vamknam.by${path==='/catalog'?'<small>изделия из дерева с душой</small>':''}</span></a><div class="header-contact"><a class="phone" href="tel:+375447535310">${icon('phone')}<span>${PHONE}</span></a><a class="telegram" href="${TG}" aria-label="Написать в Telegram">${icon('telegram')}<span>Telegram</span></a></div><nav id="main-nav" aria-label="Главная навигация"><a href="catalog/" ${path==='/catalog'?'aria-current="page"':''}>Каталог</a><a href="how-to-order/" ${order?'aria-current="page"':''}>Как заказать</a><a href="./#about">О мастере</a><a href="./#reviews">Отзывы</a><a href="./#contacts">Контакты</a></nav><a class="header-cart" href="cart/" aria-label="Корзина">${icon('cart')}<span data-cart-count>0</span></a><button class="menu-toggle" id="menu-toggle" aria-label="Открыть меню" aria-controls="main-nav" aria-expanded="false">${icon('menu')}</button></div>`;}
function footer(){(document.querySelector('#footer')||document.querySelector('footer')).innerHTML=`<div class="footer-inner"><a href="./">vamknam.by</a><span>Изделия из дерева с душой</span><a href="${IG}" target="_blank" rel="noopener">Instagram @vamknam.by</a><a href="cart/">Корзина (<span data-cart-count>0</span>)</a></div>`;}
function title(text){return `<h2 class="ornament-heading"><span>${icon('diamond')}</span>${text}<span>${icon('diamond')}</span></h2>`;}
function productCard(p,compact=false){return `<article class="product-card ${compact?'compact-card':''}"><a class="card-image" href="${productURL(p)}">${photo(p.homeImage||p.image,p.name)}</a><div class="card-info"><h3><a href="${productURL(p)}">${esc(p.name)}</a></h3>${p.id==='custom'?'<p class="card-subtitle">Ваш дизайн или идея</p>':''}<p class="card-price">${priceHTML(p)}</p><a class="order-button" href="${p.id==='custom'?'how-to-order/?custom=1':productURL(p)}">Хочу заказать</a></div></article>`;}
function home(){document.title='vamknam.by — изделия из дерева с душой';app.innerHTML=`<section class="hero"><div class="hero-photo">${photo('hero','Ключница из дерева с веткой и листьями','',true)}</div><div class="home-container hero-inner"><div class="hero-copy"><h1>Создаём то, что<br>не купишь в магазине.</h1><p>Авторские ключницы, копилки и панели из дерева,<br class="desktop-break"> сделанные лазерной резкой с душой и вниманием к деталям.</p><a class="button" href="catalog/">Смотреть работы ${icon('arrow')}</a></div></div></section><div class="home-container home-sections"><section class="hits">${title('Хиты сезона')}<div class="featured-grid">${products.slice(0,4).map(p=>productCard(p,true)).join('')}</div></section><section class="categories">${title('Каталог изделий')}<div class="category-grid">${[['Блокноты','notebook'],['Копилки','pig-bank'],['Мини-бары','mini-bar'],['Ключницы','leaves']].map(([name,img])=>`<a class="category-card" href="catalog/?category=${encodeURIComponent(name)}">${photo(img,name)}<h3>${name}</h3></a>`).join('')}</div></section><section class="how-works">${title('Как это работает')}<div class="steps">${[['search','Выбираете изделие','Смотрите каталог и выбираете то, что нравится.'],['chat','Обсуждаем детали и цену','Согласовываем дизайн, материалы и сроки.'],['leaf','Делаю и передаю','Создаю с заботой и передаю вам готовую работу.']].map(([i,h,p],n)=>`<div class="step"><span class="step-icon">${icon(i)}</span><span class="step-number">${n+1}</span><div><h3>${h}</h3><p>${p}</p></div>${n<2?icon('arrow','step-arrow'):''}</div>`).join('')}</div></section></div><div class="home-container extra-info"><section id="about"><h2>О мастере</h2><p>Создаём вещи из дерева с вниманием к деталям: от аккуратной лазерной резки до вашей личной надписи. Выберите изделие или расскажите о своей идее — обсудим оформление, цену и сроки.</p></section><section id="reviews"><h2>Отзывы</h2><p>Работы мастерской и истории заказов — в нашем Instagram.</p><a href="${IG}" target="_blank" rel="noopener">Перейти в @vamknam.by</a></section><section id="contacts"><h2>Контакты</h2><p><a href="tel:+375447535310">${PHONE}</a> · <a href="${TG}">Telegram</a> · <a href="${IG}" target="_blank" rel="noopener">Instagram</a></p><p>Детали изготовления, доставку и дату готовности согласуем при заказе.</p><a href="how-to-order/">Как заказать</a></section></div>`;}
function breadcrumb(last,extra=''){return `<div class="breadcrumb"><a href="./">Главная</a><span>›</span>${extra}${esc(last)}</div>`;}
function catalog(){const category=params.get('category')||'Ключницы';let items=category==='Ключницы'?products.filter(p=>p.catalog):products.filter(p=>p.category===category);if(!items.length)items=products.filter(p=>p.catalog);app.innerHTML=`<div class="catalog-container">${breadcrumb(category,'<a href="catalog/">Каталог</a><span>›</span>')}<h1>${esc(category)}</h1><div class="catalog-grid">${items.map(p=>productCard(p)).join('')}</div><nav class="catalog-categories" aria-label="Разделы каталога">${['Ключницы','Копилки','Блокноты','Мини-бары','Декор'].map(c=>`<a href="catalog/?category=${encodeURIComponent(c)}" ${c===category?'aria-current="page"':''}>${c}</a>`).join('')}</nav></div>`;}
function productPage(id){const p=getProduct(id);if(!p)return notFound();document.title=p.name+' — vamknam.by';const leaves=id==='leaves';const mainImage=leaves?'key-product-portrait':p.image;app.innerHTML=`<section class="product-layout"><div class="product-gallery"><div class="gallery-primary"><button class="main-photo" type="button" aria-label="Увеличить фотографию">${photo(mainImage,p.name,'',true)}</button>${leaves?`<div class="gallery-preview">${photo('key-product-flat','Ключница «Листья», вид под углом')}<button type="button" class="preview-button" aria-label="Посмотреть фотографии изделия">${icon('play')}</button><span class="preview-caption">Фотографии изделия</span></div>`:''}</div><div class="thumbnails"><button class="thumb active" data-photo="${mainImage}" aria-label="Основной вид">${photo(mainImage,'Основной вид изделия')}</button>${leaves?`<button class="thumb" data-photo="key-product-flat" aria-label="Вид под углом">${photo('key-product-flat','Изделие под углом')}</button>`:''}</div></div><div class="product-info">${breadcrumb(p.name,`<a href="catalog/">Каталог</a><span>/</span><a href="catalog/?category=${encodeURIComponent(p.category)}">${p.category}</a><span>/</span>`)}<h1>${esc(p.name)}</h1><p class="product-price">${priceHTML(p)}</p><p class="price-note">${p.price===null?'Стоимость согласовывается индивидуально':'Цена за изделие без персонализации'}</p><p class="product-description">${esc(p.description)}</p><dl class="product-specs">${[['leaf','Материал','Качественная фанера (берёза)'],['ruler','Размер',p.size||'Согласовывается при заказе'],['edit','Персонализация','Можно добавить имя или надпись'],['clock','Срок изготовления','1–2 рабочих дня']].map(([i,label,value])=>`<div>${icon(i)}<dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl><form id="product-form" data-id="${p.id}"><button class="add-to-cart" type="submit">Добавить в Корзину ${icon('cart')}</button><details class="personalization"><summary>Добавить надпись или пожелания</summary><label class="field">Ваша надпись<input name="personalization" maxlength="140" placeholder="Имя, дата или пожелание"></label><label class="field">Количество<input type="number" name="quantity" value="1" min="1" max="99" required></label></details></form></div></section><dialog id="photo-dialog"><button class="close-dialog" aria-label="Закрыть фотографию">×</button>${photo(mainImage,p.name)}<p>${esc(p.name)}</p></dialog>`;}
function orderPage(){app.innerHTML=`<div class="order-container"><h1 class="order-title">Как заказать</h1><div class="title-flourish">${icon('flower')}</div><section class="order-step"><span class="order-number">1.</span><div class="order-copy"><h2>Оформление заказа:</h2><p>Напишите нам в <a href="${TG}">Telegram</a> или <a href="tel:+375447535310">позвоните</a> и сообщите:</p><ol><li>Желаемую дату готовности (уточните доступную дату у мастера)</li><li>Номер телефона</li><li>Название изделия с деталями (размер, текст, пожелания)</li><li>Способ доставки:<ul><li>Самовывоз (Минск / Фаниполь)</li><li>Белпочта (домашний адрес)</li><li>Европочта (номер отделения + город)</li></ul></li></ol></div>${icon('edit','order-illustration')}</section><section class="order-step dates-step"><span class="order-number">2.</span><div class="order-copy"><h2>Ближайшие даты готовности и отправки</h2><div class="dates-box"><p>Свободную дату согласуем при заказе.<br>Напишите желаемый день — уточним возможность изготовления.</p>${icon('calendar')}</div><p class="dates-note">${icon('refresh')} даты обновляются — уточняйте у мастера</p></div></section><section class="order-step pickup-step"><span class="order-number">3.</span><div class="order-copy"><h2>Самовывоз</h2><p>${icon('pin')} Минск: пр. Дзержинского 126 (стоянка «Простор», ст.м. Малиновка) — после 18:30</p><p>${icon('pin')} Фаниполь: ул. Зелёная — после 18:00</p></div>${icon('home','order-illustration')}</section><section class="order-step mail-step"><span class="order-number">4.</span><div class="order-copy"><h2>Почта</h2><p>Отправляем после 18:00. Оплата на карту после отправки или после получения.</p></div>${icon('parcel','order-illustration')}</section><section class="order-request" id="request"><h2>${params.has('custom')?'Ваша идея на заказ':'Подготовить заявку'}</h2><p>Составьте сообщение, скопируйте его и отправьте мастеру.</p><form id="order-form"><div class="form-grid"><label class="field">Ваше имя<input name="name" maxlength="80" autocomplete="given-name" required></label><label class="field">Телефон<input name="phone" type="tel" autocomplete="tel" maxlength="30" required></label><label class="field">Желаемая дата<input name="date" type="date"></label><label class="field">Получение<select name="delivery"><option>Уточнить при заказе</option><option>Самовывоз — Минск</option><option>Самовывоз — Фаниполь</option><option>Белпочта</option><option>Европочта</option></select></label></div><label class="field">Изделие, надпись и пожелания<textarea name="idea" maxlength="2000" ${cart.length?'':'required'} placeholder="Название изделия, количество, размер и желаемая надпись"></textarea></label><button class="button" type="submit">Составить сообщение ${icon('arrow')}</button><div id="order-result"></div></form></section></div>`;if(params.has('checkout')||params.has('custom'))requestAnimationFrame(()=>document.querySelector('#request').scrollIntoView());}
function cartPage(){document.title='Корзина — vamknam.by';app.innerHTML=`<div class="standard-container">${breadcrumb('Корзина')}<h1>Корзина</h1>${cart.length?`<div class="cart-layout"><div>${cart.map((x,i)=>{const p=getProduct(x.id);return `<article class="cart-row"><a href="${productURL(p)}">${photo(p.image,p.name)}</a><div><h2><a href="${productURL(p)}">${esc(p.name)}</a></h2><p>${esc(x.text)||'Без персонализации'}</p><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="Уменьшить количество ${esc(p.name)}">−</button><span>${x.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Увеличить количество ${esc(p.name)}">+</button></div></div><div class="cart-item-price">${p.price===null?'По запросу':p.price*x.qty+' BYN'}<button class="remove" data-remove="${i}">Убрать</button></div></article>`}).join('')}</div><aside class="cart-total"><h2>Ваш заказ</h2><p>Предварительно: <strong>${cart.some(x=>getProduct(x.id).price===null)?'уточняется':cart.reduce((n,x)=>n+(getProduct(x.id).price||0)*x.qty,0)+' BYN'}</strong></p><p>Персонализация и доставка согласовываются отдельно. Итоговую стоимость и сроки подтвердит мастер.</p><a class="button" href="how-to-order/?checkout=1">Оформить заявку ${icon('arrow')}</a></aside></div>`:`<div class="empty-cart"><p>В корзине пока нет изделий.</p><a class="button" href="catalog/">Перейти в каталог ${icon('arrow')}</a></div>`}</div>`;}
function notFound(){app.innerHTML='<div class="standard-container"><h1>Страница не найдена</h1><p><a href="./">На главную</a></p></div>';}
function addCart(id,text='',qty=1){const same=cart.find(x=>x.id===id&&x.text===text);if(same)same.qty=Math.min(99,same.qty+qty);else cart.push({id,text,qty});saveCart();toast('Изделие добавлено в корзину');}
header();footer();
if(path==='/')home();else if(path==='/catalog')catalog();else if(path==='/how-to-order')orderPage();else if(path==='/cart')cartPage();else if(path.startsWith('/product')){const slug=path.split('/')[2];productPage(params.get('id')||(slug==='klyuchnitsa-listya'?'leaves':({savings:'house',cannon:'mini-bar',pen:'notebook'})[slug]||slug)||'leaves');}else notFound();
saveCart();
document.querySelector('#menu-toggle').addEventListener('click',e=>{const btn=e.currentTarget;const open=btn.getAttribute('aria-expanded')!=='true';btn.setAttribute('aria-expanded',open);btn.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');document.querySelector('#main-nav').classList.toggle('open',open);});
document.addEventListener('click',e=>{
 const thumb=e.target.closest('[data-photo]');if(thumb){const name=thumb.dataset.photo;document.querySelector('.main-photo img').src=A+name+'.jpg';document.querySelector('#photo-dialog img').src=A+name+'.jpg';document.querySelectorAll('.thumb').forEach(el=>el.classList.toggle('active',el===thumb));}
 if(e.target.closest('.main-photo'))document.querySelector('#photo-dialog').showModal();
 if(e.target.closest('.close-dialog'))document.querySelector('#photo-dialog').close();
 if(e.target.closest('.preview-button')){document.querySelector('.main-photo img').src=A+'key-product-flat.jpg';document.querySelector('#photo-dialog img').src=A+'key-product-flat.jpg';document.querySelector('#photo-dialog').showModal();}
 const qty=e.target.closest('[data-qty]');if(qty){const x=cart[Number(qty.dataset.qty)];x.qty=Math.max(1,Math.min(99,x.qty+Number(qty.dataset.delta)));saveCart();cartPage();}
 const remove=e.target.closest('[data-remove]');if(remove){cart.splice(Number(remove.dataset.remove),1);saveCart();cartPage();}
 if(e.target.closest('#copy-order'))copyOrder();
 if(e.target.closest('#main-nav a')){document.querySelector('#main-nav').classList.remove('open');document.querySelector('#menu-toggle').setAttribute('aria-expanded','false');}
});
let orderSummary='';
document.addEventListener('submit',e=>{
 if(e.target.id==='product-form'){e.preventDefault();const d=new FormData(e.target);addCart(e.target.dataset.id,String(d.get('personalization')||'').trim(),Math.min(99,Math.max(1,Number(d.get('quantity'))||1)));}
 if(e.target.id==='order-form'){e.preventDefault();const d=new FormData(e.target);orderSummary=`Здравствуйте! Меня зовут ${d.get('name')}. Хочу оформить заказ.\nТелефон: ${d.get('phone')}\n\n${cart.map(x=>{const p=getProduct(x.id);return `${p.name} — ${x.qty} шт., ${p.price===null?'цена по запросу':p.price*x.qty+' BYN'}${x.text?'\nНадпись: '+x.text:''}`;}).join('\n')}\n${d.get('idea')?'Пожелания: '+d.get('idea')+'\n':''}${d.get('date')?'Желаемая дата: '+d.get('date')+'\n':''}Получение: ${d.get('delivery')}.\nПодтвердите, пожалуйста, стоимость и сроки изготовления.`;document.querySelector('#order-result').innerHTML=`<h3>Сообщение готово</h3><p>Заявка ещё не отправлена. Скопируйте текст и отправьте мастеру в Telegram или Instagram.</p><textarea class="summary-box" readonly aria-label="Текст заявки">${esc(orderSummary)}</textarea><div class="result-actions"><button class="button" type="button" id="copy-order">Скопировать</button><a class="button" href="${TG}">Telegram</a><a class="button" href="${IG}" target="_blank" rel="noopener">Instagram</a></div>`;document.querySelector('#order-result').scrollIntoView({behavior:'smooth',block:'center'});}
});
async function copyOrder(){try{await navigator.clipboard.writeText(orderSummary);document.querySelector('#copy-order').textContent='Скопировано';toast('Сообщение скопировано');}catch{document.querySelector('.summary-box').select();toast('Выделенный текст можно скопировать вручную');}}
if(location.hash)requestAnimationFrame(()=>document.querySelector(location.hash)?.scrollIntoView());
